package com.asmj.marketplace.controller;

import com.asmj.marketplace.model.Role;
import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.order.*;
import com.asmj.marketplace.product.*;
import com.asmj.marketplace.repository.UserAccountRepository;
import com.asmj.marketplace.service.CloudinaryImageService;
import java.security.Principal;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class ProductReviewController {
 private final ProductRepository products; private final ProductReviewRepository reviews; private final MarketplaceOrderRepository orders; private final UserAccountRepository users; private final CloudinaryImageService uploads;
 public ProductReviewController(ProductRepository products,ProductReviewRepository reviews,MarketplaceOrderRepository orders,UserAccountRepository users,CloudinaryImageService uploads){this.products=products;this.reviews=reviews;this.orders=orders;this.users=users;this.uploads=uploads;}
 @GetMapping("/products/{id}") public String detail(@PathVariable String id,Model model){Product product=products.findById(id).filter(p->p.getStatus()==ProductStatus.ACTIVE).orElseThrow();List<ProductReview> approved=reviews.findByProductIdAndStatusOrderByCreatedAtDesc(id,ProductReview.ReviewStatus.APPROVED);double average=approved.stream().mapToInt(ProductReview::getRating).average().orElse(0);model.addAttribute("product",product);model.addAttribute("reviews",approved);model.addAttribute("reviewCount",approved.size());model.addAttribute("averageRating",average);return "product/detail";}
 @PostMapping("/customer/reviews") public String submit(@RequestParam String productId,@RequestParam String orderId,@RequestParam int rating,@RequestParam(required=false) String title,@RequestParam(required=false) String comment,@RequestParam(required=false) MultipartFile image,Principal principal,RedirectAttributes redirect){UserAccount customer=users.findByEmailIgnoreCase(principal.getName()).orElseThrow();if(customer.getRole()!=Role.ROLE_CUSTOMER)return "auth/access-denied";Product product=products.findById(productId).filter(p->p.getStatus()==ProductStatus.ACTIVE||p.getStatus()==ProductStatus.ARCHIVED).orElse(null);MarketplaceOrder order=orders.findById(orderId).orElse(null);if(product==null||order==null||!customer.getId().equals(order.getCustomerUserId())||order.getStatus()!=OrderStatus.COMPLETED||order.getPaymentStatus()!=PaymentStatus.VERIFIED||order.getItems().stream().noneMatch(i->productId.equals(i.getProductId()))){redirect.addFlashAttribute("errorMessage","Only customers with a completed and payment-verified order for this product can submit a review.");return "redirect:/customer/orders";}if(rating<1||rating>5){redirect.addFlashAttribute("errorMessage","Choose a rating from 1 to 5 stars.");return "redirect:/customer/orders";}if(reviews.existsByProductIdAndCustomerUserIdAndOrderId(productId,customer.getId(),orderId)){redirect.addFlashAttribute("errorMessage","You have already reviewed this product for that order.");return "redirect:/customer/orders";}try{ProductReview review=new ProductReview();review.setProductId(productId);review.setVendorUserId(product.getVendorUserId());review.setCustomerUserId(customer.getId());review.setOrderId(orderId);review.setOrderNumber(order.getOrderNumber());review.setProductName(product.getName());review.setCustomerName(customer.getFullName());review.setRating(rating);review.setTitle(title==null?"":title.trim());review.setComment(comment==null?"":comment.trim());if(review.getComment().length()>2000||review.getTitle().length()>120)throw new IllegalArgumentException("Review title or comment is too long.");if(image!=null&&!image.isEmpty()){String type=image.getContentType()==null?"":image.getContentType().toLowerCase();if(!java.util.Set.of("image/jpeg","image/png","image/webp").contains(type))throw new IllegalArgumentException("Review photos must be JPG, PNG or WEBP images.");Map<String,Object> file=uploads.uploadDocument(image,"asmj-marketplace/product-reviews");review.setImageUrl(String.valueOf(file.get("secure_url")));review.setImageFileName(image.getOriginalFilename());}review.setStatus(ProductReview.ReviewStatus.PENDING);review.setCreatedAt(Instant.now());review.setUpdatedAt(Instant.now());reviews.save(review);redirect.addFlashAttribute("successMessage","Thank you. Your review was submitted for moderation.");}catch(IllegalArgumentException|IllegalStateException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return "redirect:/customer/orders";}
 @GetMapping("/vendor/reviews") public String vendorReviews(Principal principal,Model model){UserAccount vendor=users.findByEmailIgnoreCase(principal.getName()).orElseThrow();model.addAttribute("reviews",reviews.findByVendorUserIdOrderByCreatedAtDesc(vendor.getId()));return "vendor/reviews";}
 @PostMapping("/vendor/reviews/{id}/reply") public String vendorReply(@PathVariable String id,@RequestParam String reply,Principal principal,RedirectAttributes redirect){UserAccount vendor=users.findByEmailIgnoreCase(principal.getName()).orElseThrow();ProductReview review=reviews.findById(id).orElseThrow();if(!vendor.getId().equals(review.getVendorUserId()))return "auth/access-denied";if(review.getStatus()!=ProductReview.ReviewStatus.APPROVED||reply==null||reply.isBlank()||reply.trim().length()>1000){redirect.addFlashAttribute("errorMessage","Only approved reviews can receive a reply (maximum 1,000 characters).");return "redirect:/vendor/reviews";}review.setVendorReply(reply.trim());review.setVendorReplyAt(Instant.now());review.setUpdatedAt(Instant.now());reviews.save(review);redirect.addFlashAttribute("successMessage","Your reply has been published.");return "redirect:/vendor/reviews";}
 @GetMapping("/admin/reviews") public String adminReviews(Model model){model.addAttribute("reviews",reviews.findByStatusOrderByCreatedAtDesc(ProductReview.ReviewStatus.PENDING));return "admin/reviews";}
 @PostMapping("/admin/reviews/{id}/moderate") public String moderate(@PathVariable String id,@RequestParam ProductReview.ReviewStatus status,RedirectAttributes redirect){if(status!=ProductReview.ReviewStatus.APPROVED&&status!=ProductReview.ReviewStatus.REJECTED){redirect.addFlashAttribute("errorMessage","Invalid moderation status.");return "redirect:/admin/reviews";}ProductReview review=reviews.findById(id).orElseThrow();review.setStatus(status);review.setUpdatedAt(Instant.now());reviews.save(review);redirect.addFlashAttribute("successMessage","Review moderation updated.");return "redirect:/admin/reviews";}
}
